def match(orders):
    import heapq

    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq','active'}
    trades = []
    seq_counter = [0]

    def add_resting(side, id, price, qty):
        s = seq_counter[0]
        seq_counter[0] += 1
        book[id] = {'side': side, 'price': price, 'qty': qty, 'seq': s, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, s, id))
        else:
            heapq.heappush(sell_heap, (price, s, id))

    def pop_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return item
        return None

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            item = pop_valid(opp_heap)
            if item is None:
                break
            opp_id = item[2]
            opp_o = book[opp_id]
            opp_price_actual = opp_o['price']

            if typ == 'market':
                match_ok = True
            else:
                if side == 'buy':
                    match_ok = opp_price_actual <= price
                else:
                    match_ok = opp_price_actual >= price

            if not match_ok:
                break

            trade_qty = min(remaining, opp_o['qty'])
            if side == 'buy':
                trades.append([oid, opp_id, opp_price_actual, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price_actual, trade_qty])

            remaining -= trade_qty
            opp_o['qty'] -= trade_qty
            if opp_o['qty'] == 0:
                opp_o['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            add_resting(side, oid, price, remaining)
        # ioc/market: discard remainder; fully filled limit: nothing to do

    return trades

